1234:     case "stream_request_start": {
1235:       // Sub-agent request starts carry agentId via the engine wrapper and do
1236:       // not open a main assistant slot. Top-level starts have no agentId and
1237:       // must not be routed based on the activeAgents table, which can contain
1238:       // stale/orphan cleanup state during replay and background handoffs.
1239:       if (event.agentId) {
1240:         const index = state.agentMessageIndex[event.agentId];
1241:         const agent = index === undefined ? undefined : state.messages[index];
1242:         if (agent?.kind !== "agent" || agent.done) return state;
1243:         if (event.messageId === agent.streamingTextRequest?.messageId) return state;
1244:         // Legacy starts without an id still leave displayed text untouched,
1245:         // but cannot let an older request claim later uncorrelated deltas.
1246:         const messages = [...state.messages];
1247:         messages[index!] = {
1248:           ...agent,
1249:           streamingTextRequest: event.messageId
1250:             ? {
1251:                 messageId: event.messageId,
1252:                 startOffset: (agent.text?.length ?? 0) + agent.textBuffer.length,
1253:               }
1254:             : undefined,
1255:         };
1256:         return { ...state, messages };
1257:       }
1258:       const id = event.messageId ?? freshId("assistant");
1259:       const startedAt = now();
1260:       const previousId = state.streamingAssistantId;
1261:       const messages = previousId
1262:         ? state.messages.map((m) =>
1263:             m.kind === "assistant" && m.id === previousId && !m.done
1264:               ? { ...m, done: true, doneAt: m.doneAt ?? startedAt }
1265:               : m,
1266:           )
1267:         : state.messages;
1268:       return {
1269:         ...state,
1270:         messages: [
1271:           ...withTurnTiming(messages, event, startedAt),
1272:           { kind: "assistant", id, text: "", done: false, createdAt: startedAt },
1273:         ],
1274:         streamingAssistantId: id,
1275:         streamingThinkingId: null,
1276:       };
1277:     }
